```javascript
const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = input[0];
const values = input.slice(1, n + 1);
const height = Math.max(...values);
const output = [];

for (let level = height; level >= 1; level--) {
  output.push(values.map(value => value >= level ? 1 : 0).join(' '));
}

console.log(output.join('\n'));
